import pytest

from sales_dashboard.loader import daily_conversion_counts, dedupe_sessions, parse_session_log
from sales_dashboard.metrics import (
    conversion_rate,
    conversion_rate_by_group,
    conversions_in_window,
    longest_conversion_streak,
    pooled_conversion_rate,
)
from sales_dashboard.report import campaign_summary, top_converting_groups


def test_conversion_rate_counts_none_as_not_converted():
    assert conversion_rate([{"converted": True}, {"converted": None}]) == 0.5
    assert conversion_rate([]) == 0.0


def test_dedupe_keeps_last_record_then_sorts_by_day_and_id():
    events = parse_session_log(["a,9,1", "b,2,1", "a,2,0", "z,1,"])
    assert dedupe_sessions(events) == [events[3], events[2], events[1]]


def test_parser_skips_comments_and_blank_lines_and_strips_fields():
    assert parse_session_log(["", " \t", "  # header", " a , 3 , 0 ", "b,4, "]) == [
        {"id": "a", "day": 3, "converted": False},
        {"id": "b", "day": 4, "converted": None},
    ]


@pytest.mark.parametrize('line', ['x,1', 'x,1,0,extra', 'x,day,1'])
def test_parser_reports_original_line_number(line):
    with pytest.raises(ValueError, match=r'\bline 4\b'):
        parse_session_log(['', '  # comment', 'ok,1,1', line])


def test_trailing_window_sizes():
    counts = [1, 2, 3]
    assert conversions_in_window(counts, 2) == 5
    assert conversions_in_window(counts, 0) == 0
    assert conversions_in_window(counts, 4) == 6


def test_daily_counts_respect_bounds_and_fill_gaps():
    events = parse_session_log(['a,1,1', 'b,2,1', 'c,2,1', 'd,4,0', 'e,5,1'])
    assert daily_conversion_counts(events, 2, 4) == [2, 0, 0]
    assert daily_conversion_counts(events, 3, 2) == []


def test_campaign_uses_pooled_rate_and_calendar_days():
    groups = {'empty': [], 'a': parse_session_log(['x,1,1']),
              'b': parse_session_log(['y,2,1', 'z,4,0'])}
    assert campaign_summary(groups, 2) == {'rate': 0.667, 'recent': 0, 'groups': 2}
    assert campaign_summary({'empty': []}, 5) == {'rate': 0.0, 'recent': 0, 'groups': 0}
    assert pooled_conversion_rate({}) == 0.0


def test_group_rates_and_ranking_order():
    groups = {'z': [], 'c': [{'converted': False}], 'b': [{'converted': True}],
              'a': [{'converted': True}]}
    assert list(conversion_rate_by_group(groups).items()) == [
        ('a', 1.0), ('b', 1.0), ('c', 0.0), ('z', None)]
    assert top_converting_groups(groups, 1) == ['a']
    assert top_converting_groups(groups, 5) == ['a', 'b', 'c']


def test_streak_resets_on_nonpositive_counts():
    assert longest_conversion_streak([1, 0, 1, 2, -1, 1]) == 2
    assert longest_conversion_streak([]) == 0
